const iframe=document.querySelector('#demo'),result=document.querySelector('#result'),cases=[];
const check=(v,m)=>{if(!v)throw Error(m)},frame=()=>new Promise(r=>requestAnimationFrame(r)),wait=async(n=5)=>{for(let i=0;i<n;i++)await frame()};
try{
 let canvas;for(let i=0;i<1200;i++){canvas=iframe.contentDocument?.querySelector('canvas');const error=iframe.contentDocument?.querySelector('#status[data-state=error]');if(error)throw Error(error.textContent);if(canvas?.dataset.ready==='true'&&canvas.dataset.snapshot)break;await frame();}
 check(canvas?.dataset.snapshot,'Registered example did not become ready');const adapter=JSON.parse(canvas.dataset.adapter);check(adapter.isFallbackAdapter===false,'Native example adapter required');const read=()=>JSON.parse(canvas.dataset.snapshot),click=y=>{const box=canvas.getBoundingClientRect(),w=iframe.contentWindow;for(const type of ['pointerdown','pointerup'])canvas.dispatchEvent(new w.PointerEvent(type,{clientX:box.x+60,clientY:box.y+y,pointerId:1,pointerType:'mouse',buttons:type==='pointerdown'?1:0,bubbles:true}));};
 await wait(10);let before=read();await wait(8);let after=read();check(after.sceneRecords>before.sceneRecords&&after.guiRecords===before.guiRecords&&after.guiLayouts===before.guiLayouts&&after.guiUploads===before.guiUploads,'Continuous example did not skip unchangedGUI');cases.push({id:'continuous-with-cached-GUI',before,after});
 click(180);await wait(2);after=read();check(after.changes===1&&after.guiRecords>before.guiRecords,'GUI canvas interaction did not invalidate on next frame');cases.push({id:'GUI-interaction',after});
 click(130);await wait(10);before=read();await wait(8);after=read();check(!after.playing&&after.frames>before.frames&&after.sceneRecords===before.sceneRecords&&after.guiRecords===before.guiRecords&&after.regions.presentations===0,'Pause did not reach all-static zero rendering while clock advances');cases.push({id:'pause-all-idle',before,after});
 click(130);await wait(10);before=read();await wait(8);after=read();check(after.playing&&after.sceneRecords>before.sceneRecords&&after.guiRecords===before.guiRecords,'Resume did not independently wake3D');cases.push({id:'resume',before,after});
 iframe.style.width='800px';iframe.style.height='480px';await wait(20);after=read();check(after.playing&&after.regions.presentations===1,'Example did not recover from resize');cases.push({id:'resize',after,width:canvas.width,height:canvas.height});
 const previewPngDataUrl=canvas.toDataURL('image/png'),image=new Image();image.src=previewPngDataUrl;await image.decode();const capture=document.createElement('canvas');capture.width=image.naturalWidth;capture.height=image.naturalHeight;const ctx=capture.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);const dpr=canvas.width/canvas.clientWidth,sidebar=Math.min(260,canvas.clientWidth*.3),pixel=(x,y)=>Array.from(ctx.getImageData(Math.floor(x*dpr),Math.floor(y*dpr),1,1).data),background=pixel(8,350),mesh=pixel((sidebar+canvas.clientWidth)/2,canvas.clientHeight/2);check(background.slice(0,3).every((v,i)=>Math.abs(v-[24,36,58][i])<=3),'Actual example sidebar pixels incorrect');check(mesh.slice(0,3).reduce((a,b)=>a+b,0)>200,'Actual example 3D mesh not visible');cases.at(-1).visual={background,mesh,width:capture.width,height:capture.height};
 iframe.contentWindow.dispatchEvent(new iframe.contentWindow.PageTransitionEvent('pagehide'));check(canvas.dataset.destroyed==='true','Example pagehide did not destroy engine');const cleanup=JSON.parse(canvas.dataset.cleanup);check((cleanup.buffer?.current??0)===0&&(cleanup.texture?.current??0)===0,'Engine teardown retained buffers/textures');cases.push({id:'pagehide',cleanup});
 result.textContent=JSON.stringify({status:'passed',caseCount:cases.length,cases,adapter,previewPngDataUrl,qualification:'Registered public-import example structural interaction, pause/business clock, wake, resize and official engine teardown; native direct/cache pixels are verified separately.'});result.dataset.status='passed';
}catch(error){result.textContent=JSON.stringify({status:'failed',error:String(error.stack??error),cases});result.dataset.status='failed';}
